// Configure competitor URLs to monitor
const competitors = [
  {
    name: $env.COMPETITOR_1_NAME || 'Concurrent 1',
    website: $env.COMPETITOR_1_URL || 'https://competitor1.com',
    social: {
      facebook: $env.COMPETITOR_1_FB || '',
      instagram: $env.COMPETITOR_1_IG || '',
      tiktok: $env.COMPETITOR_1_TT || ''
    }
  },
  {
    name: $env.COMPETITOR_2_NAME || 'Concurrent 2',
    website: $env.COMPETITOR_2_URL || 'https://competitor2.com',
    social: {
      facebook: $env.COMPETITOR_2_FB || '',
      instagram: $env.COMPETITOR_2_IG || '',
      tiktok: $env.COMPETITOR_2_TT || ''
    }
  },
  {
    name: $env.COMPETITOR_3_NAME || 'Concurrent 3',
    website: $env.COMPETITOR_3_URL || 'https://competitor3.com',
    social: {
      facebook: $env.COMPETITOR_3_FB || '',
      instagram: $env.COMPETITOR_3_IG || '',
      tiktok: $env.COMPETITOR_3_TT || ''
    }
  }
];

return competitors.map(c => ({ json: c }));

// Extract key info from scraped website
const html = $('Scrape Website').item.json.data || '';
const competitorInfo = $('Configure Competitors').item.json;
const searchResults = $('Search Competitor Mentions').item.json;

// Extract meta info from HTML
const titleMatch = html.match(/<title>(.*?)<\/title>/i);
const descMatch = html.match(/<meta\s+name=["']description["']\s+content=["'](.*?)["']/i);
const h1Match = html.match(/<h1[^>]*>(.*?)<\/h1>/gi);

const extracted = {
  competitor: competitorInfo,
  website_data: {
    title: titleMatch ? titleMatch[1] : 'N/A',
    meta_description: descMatch ? descMatch[1] : 'N/A',
    h1_tags: h1Match ? h1Match.map(h => h.replace(/<[^>]*>/g, '')).slice(0, 5) : []
  },
  search_presence: {
    organic_results_count: searchResults?.organic_results?.length || 0,
    top_results: (searchResults?.organic_results || []).slice(0, 5).map(r => ({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    })),
    ads_present: (searchResults?.ads || []).length > 0,
    ads_count: (searchResults?.ads || []).length
  }
};

return { json: extracted };

